"""Shared contract for text plans generated by the frozen action Teacher."""
from __future__ import annotations


def plan_token_budget(settings: dict) -> int:
    """Zero selects action-only KD; a positive budget requires the online Teacher."""
    budget = settings.get("teacher_plan_max_new_tokens", 0)
    if type(budget) is not int or not 0 <= budget <= 128:
        raise ValueError("teacher_plan_max_new_tokens must be an integer in [0, 128]")
    if budget and settings.get("teacher_mode") != "inference":
        raise ValueError("Teacher plans require teacher_mode=inference")
    return budget


def normalize_plan(text: str) -> str:
    """Accept bounded plain text suitable for a Student prompt."""
    if not isinstance(text, str):
        raise ValueError("T1 plan must be text")
    text = " ".join(text.split())
    if (len(text) > 2048 or not text.isprintable() or "<" in text or ">" in text
            or not any(char.isalpha() for char in text)):
        raise ValueError("T1 emitted an invalid or empty approach plan")
    return text


def prompt_text(plan: str, timestep: int | None) -> str:
    if type(timestep) is not int or timestep < 0:
        raise ValueError("Teacher plan requires its observation timestep")
    return f"Teacher approach plan at t={timestep}: {normalize_plan(plan)}"
